(function(){"use strict";document.querySelectorAll(".reviews-section").forEach(function(section){const track=section.querySelector(".reviews-track");const cards=Array.from(track.querySelectorAll(".review-card"));const previous=section.querySelector("[data-review-prev]");const next=section.querySelector("[data-review-next]");const status=section.querySelector(".reviews-status");const motion=window.matchMedia("(prefers-reduced-motion: reduce)");let reviewsFrame=false;function updateReviews(){reviewsFrame=false;const viewport=track.getBoundingClientRect();const visible=cards.map(function(card,index){const box=card.getBoundingClientRect();return box.left>=viewport.left-8&&box.left<viewport.right-32?index+1:null}).filter(Boolean);const scrollLeft=track.scrollLeft;const atStart=scrollLeft<=2;const atEnd=scrollLeft>=track.scrollWidth-track.clientWidth-3;if(previous.disabled!==atStart)previous.disabled=atStart;if(next.disabled!==atEnd)next.disabled=atEnd;if(visible.length){const message=(visible.length===1?"Depoimento "+visible[0]:"Depoimentos "+visible[0]+" a "+visible[visible.length-1])+" de "+cards.length;if(status.textContent!==message)status.textContent=message}}function scheduleReviews(){if(!reviewsFrame){reviewsFrame=true;window.requestAnimationFrame(updateReviews)}}function moveReviews(direction){const gap=parseFloat(getComputedStyle(track).columnGap)||0;const width=cards[0].getBoundingClientRect().width+gap;const count=Math.max(1,Math.round((track.clientWidth+gap)/width));track.scrollBy({left:direction*count*width,behavior:motion.matches?"instant":"smooth"})}previous.addEventListener("click",function(){moveReviews(-1)});next.addEventListener("click",function(){moveReviews(1)});track.addEventListener("scroll",scheduleReviews,{passive:true});window.addEventListener("resize",scheduleReviews);section.querySelectorAll(".review-read-more").forEach(function(button){button.addEventListener("click",function(){const expanded=button.getAttribute("aria-expanded")!=="true";button.setAttribute("aria-expanded",String(expanded));button.closest(".review-card").classList.toggle("expanded",expanded);button.textContent=expanded?"Ler menos":"Ler mais"})});updateReviews()});if(window.location.hash){document.body.classList.add("preview-deep-link");let interacted=false;["wheel","touchstart","keydown"].forEach(function(name){window.addEventListener(name,function(){interacted=true},{once:true,passive:true})});window.addEventListener("load",async function(){if(document.fonts)await document.fonts.ready;let target;try{target=document.getElementById(decodeURIComponent(window.location.hash.slice(1)))}catch(_){return}if(target&&!interacted)target.scrollIntoView({behavior:"instant",block:"start"})},{once:true})}if("IntersectionObserver"in window){const visibleSections=new Set;const contactBoundaries=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting)visibleSections.add(entry.target);else visibleSections.delete(entry.target)});document.body.classList.toggle("footer-in-view",visibleSections.size>0)});document.querySelectorAll("footer,#contato").forEach(function(section){contactBoundaries.observe(section)})}document.addEventListener("click",function(event){const toggle=event.target.closest("footer .accordeon .open-item");if(toggle)toggle.setAttribute("aria-expanded",String(toggle.classList.contains("open")))})})();